@Service @Transactional
public class ShopService {
 @PersistenceContext EntityManager em;
 final PasswordEncoder encoder; final SimpMessagingTemplate socket; final JavaMailSender mail;
 final boolean demo,mailEnabled; final String mailFrom;
 public ShopService(PasswordEncoder encoder,SimpMessagingTemplate socket,JavaMailSender mail,@Value("${uteb.demo:false}")boolean demo,@Value("${uteb.mail.enabled:false}")boolean mailEnabled,@Value("${uteb.mail.from}")String mailFrom){this.encoder=encoder;this.socket=socket;this.mail=mail;this.demo=demo;this.mailEnabled=mailEnabled;this.mailFrom=mailFrom;}
 static void require(boolean ok,String message){if(!ok)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
 static void forbidden(boolean ok){if(!ok)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Bạn không có quyền truy cập dữ liệu này.");}
 static String str(Map<String,?> m,String k){Object v=m.get(k);return v==null?"":v.toString().trim();}
 static long number(Map<String,?>m,String k){try{return Long.parseLong(str(m,k));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Giá trị không hợp lệ: "+k);}}
 static BigDecimal money(BigDecimal n){return n.setScale(0,RoundingMode.HALF_UP);}
 String hashPassword(String password){return encoder.encode(password);}
 boolean demoMode(){return demo;}
 void revokeTokens(){try{me().tokenVersion++;}catch(ResponseStatusException ignored){}}
 void expirePayments(){for(MealOrder o:em.createQuery("from MealOrder where status='NEW' and paymentMethod <> 'COD' and paymentStatus <> 'PAID' and paymentExpires < :now",MealOrder.class).setParameter("now",LocalDateTime.now()).getResultList())expirePaymentOrder(o);}
 void expirePaymentOrder(MealOrder o){em.lock(o,LockModeType.PESSIMISTIC_WRITE);if(!"NEW".equals(o.status)||"PAID".equals(o.paymentStatus)||o.paymentExpires.isAfter(LocalDateTime.now()))return;for(OrderLine l:where(OrderLine.class,"orderId",o.id)){Product p=get(Product.class,l.productId);em.lock(p,LockModeType.PESSIMISTIC_WRITE);p.stock+=l.quantity;}o.status="CANCELLED";o.paymentStatus="REVIEW_REQUIRED".equals(o.paymentStatus)?"REVIEW_REQUIRED":"EXPIRED";event(o,"CANCELLED","Hết thời gian thanh toán, đã trả tồn kho",null);notifyUser(o.userId,o.id,"Đơn "+o.code+" đã hết thời gian thanh toán.");}
 <T> T save(T entity){em.persist(entity);return entity;}
 <T> T get(Class<T> type,long id){T v=em.find(type,id);if(v==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy dữ liệu.");return v;}
 <T> List<T> all(Class<T> type){return em.createQuery("from "+type.getAnnotation(Entity.class).name()+" order by id desc",type).getResultList();}
 <T> List<T> where(Class<T> type,String property,Object value){return em.createQuery("from "+type.getAnnotation(Entity.class).name()+" where "+property+"=:v order by id desc",type).setParameter("v",value).getResultList();}
 Account byEmail(String email){return em.createQuery("from Account where email=:e",Account.class).setParameter("e",email.toLowerCase(Locale.ROOT)).getResultStream().findFirst().orElse(null);}
 Account me(){var auth=SecurityContextHolder.getContext().getAuthentication();Account a=auth==null?null:byEmail(auth.getName());if(a==null||!a.active||!a.verified)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Vui lòng đăng nhập bằng tài khoản đã xác thực.");return a;}
 boolean has(Account a,String...roles){return Arrays.stream(roles).anyMatch(r->Arrays.asList(a.roles.split(",")).contains(r));}
 boolean managerUserTarget(Account a){return has(a,"STAFF","SHIPPER")&&Arrays.stream(a.roles.split(",",-1)).allMatch(r->List.of("CUSTOMER","STAFF","SHIPPER").contains(r));}
 void manageStore(Account a,Long storeId){forbidden(has(a,"ADMIN")||(has(a,"STAFF","MANAGER","VENDOR")&&Objects.equals(a.storeId,storeId)));}
 void managerStore(Account a,Long storeId){forbidden(has(a,"ADMIN")||(has(a,"MANAGER","VENDOR")&&Objects.equals(a.storeId,storeId)));}
 Map<String,Object> publicData(){Map<String,Object>d=new LinkedHashMap<>();d.put("stores",all(Store.class).stream().filter(s->s.active).sorted(Comparator.comparing(s->s.id)).toList());d.put("products",all(Product.class).stream().filter(p->p.available&&get(Store.class,p.storeId).active).sorted(Comparator.comparing(p->p.id)).toList());d.put("ingredients",all(Ingredient.class).stream().filter(i->i.available).sorted(Comparator.comparing(i->i.id)).toList());d.put("categories",all(Category.class).stream().sorted(Comparator.comparing(c->c.id)).toList());d.put("promotions",all(Voucher.class).stream().filter(v->v.active&&v.userId==null&&v.endsAt.isAfter(LocalDateTime.now())&&v.startsAt.isBefore(LocalDateTime.now())).toList());d.put("reviews",all(Review.class));d.put("demo",demo);d.put("mailEnabled",mailEnabled);return d;}
 Account login(String email,String password){Account a=byEmail(email);require(a!=null&&encoder.matches(password,a.passwordHash),"Email hoặc mật khẩu không đúng.");require(a.active&&a.verified,"Tài khoản chưa xác thực hoặc đã bị khóa.");return a;}
 static void passwordValid(String password){require(password.length()>=8&&password.length()<=100,"Mật khẩu cần từ 8 đến 100 ký tự.");}
 Map<String,Object> register(Map<String,Object>b){String email=str(b,"email").toLowerCase(Locale.ROOT),name=str(b,"name"),pwd=str(b,"password"),phone=str(b,"phone");require(email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")&&email.length()<=160,"Email không hợp lệ.");require(name.length()>=2&&name.length()<=100,"Tên cần từ 2 đến 100 ký tự.");require(phone.isEmpty()||phone.matches("[+0-9 ()-]{8,20}"),"Số điện thoại không hợp lệ.");passwordValid(pwd);require(pwd.getBytes(StandardCharsets.UTF_8).length<=72,"Mật khẩu đăng ký không được vượt quá 72 byte UTF-8.");require(byEmail(email)==null,"Email đã được đăng ký.");Account a=new Account();a.email=email;a.name=name;a.phone=phone;a.birthDate=registrationBirthDate(b);a.passwordHash=encoder.encode(pwd);save(a);sendOtp(a,"VERIFY");return Map.of("message","Mã xác thực đã được gửi.");}
 LocalDate registrationBirthDate(Map<String,Object>b){
  String value=str(b,"birthDate");if(value.isEmpty())return null;
  try{LocalDate birthDate=LocalDate.parse(value);require(!birthDate.isAfter(LocalDate.now())&&!birthDate.isBefore(LocalDate.of(1900,1,1)),"Ngày sinh phải từ 01/01/1900 đến hôm nay.");return birthDate;}
  catch(java.time.format.DateTimeParseException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Ngày sinh không hợp lệ.");}
 }
 void sendOtp(Account a,String purpose){require("VERIFY".equals(purpose)||"RESET".equals(purpose),"Mục đích OTP không hợp lệ.");LocalDateTime now=LocalDateTime.now();require(a.otpSent==null||!a.otpSent.plusSeconds(60).isAfter(now),"Vui lòng chờ 60 giây trước khi gửi lại.");String code=String.format(Locale.ROOT,"%06d",new SecureRandom().nextInt(1000000));a.otpHash=encoder.encode(code);a.otpPurpose=purpose;a.otpSent=now;a.otpExpires=now.plusMinutes(5);a.otpAttempts=0;
  if(mailEnabled){String action="VERIFY".equals(purpose)?"xác thực tài khoản":"đặt lại mật khẩu";SimpleMailMessage message=new SimpleMailMessage();message.setFrom(mailFrom);message.setTo(a.email);message.setSubject("UTEB – mã "+action);message.setText("Mã "+action+" của bạn: "+code+". Có hiệu lực trong 5 phút.");try{mail.send(message);}catch(org.springframework.mail.MailException e){org.slf4j.LoggerFactory.getLogger(ShopService.class).warn("OTP delivery failed: {}",e.getClass().getSimpleName());throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Chưa gửi được email. Vui lòng thử lại sau hoặc liên hệ cửa hàng.");}}else{if(!demo)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Dịch vụ email chưa được bật. Vui lòng liên hệ cửa hàng.");try{java.nio.file.Path dir=java.nio.file.Path.of("data","mailbox");java.nio.file.Files.createDirectories(dir);java.nio.file.Files.writeString(dir.resolve(a.id+".txt"),"To: "+a.email+"\nPurpose: "+purpose+"\nOTP: "+code+"\nExpires: "+a.otpExpires,StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Không thể ghi hộp thư phát triển",e);}}
 }
 Map<String,Object> otpRequest(Map<String,Object>b){String purpose=str(b,"purpose");require("VERIFY".equals(purpose)||"RESET".equals(purpose),"Mục đích OTP không hợp lệ.");Account a=byEmail(str(b,"email"));if(a!=null){if("VERIFY".equals(purpose)&&a.verified)return Map.of("message","Tài khoản đã xác thực.");sendOtp(a,purpose);}return Map.of("message","Nếu email tồn tại, mã xác thực sẽ được gửi.");}
 boolean checkOtp(Map<String,Object>b){Account a=byEmail(str(b,"email"));String purpose=b.containsKey("password")?"RESET":"VERIFY";
  if(a==null||a.otpHash==null||a.otpExpires==null||!a.otpExpires.isAfter(LocalDateTime.now())||a.otpAttempts>=5)return false;
  if(!purpose.equals(a.otpPurpose)||(b.containsKey("purpose")&&!purpose.equals(str(b,"purpose"))))return false;
  Object code=b.get("otp");if(!(code instanceof String otp)||!otp.matches("[0-9]{6}")||!encoder.matches(otp,a.otpHash)){a.otpAttempts++;return false;}
  if("RESET".equals(a.otpPurpose)){String password=str(b,"password");passwordForAccount(password);a.passwordHash=encoder.encode(password);a.tokenVersion++;}else a.verified=true;a.otpAttempts++;a.otpHash=null;return true;
 }
 Account profile(Map<String,Object>b){Account a=me();String n=str(b,"name"),p=str(b,"phone");require(n.length()>=2&&n.length()<=100,"Tên không hợp lệ.");require(p.isEmpty()||p.matches("[+0-9 ()-]{8,20}"),"Số điện thoại không hợp lệ.");a.name=n;a.phone=p;return a;}
 static void passwordForAccount(String password){passwordValid(password);require(password.getBytes(StandardCharsets.UTF_8).length<=72,"Mật khẩu mới không được vượt quá 72 byte UTF-8.");}
 void changePassword(Map<String,Object>b){Account a=me();require(encoder.matches(str(b,"currentPassword"),a.passwordHash),"Mật khẩu hiện tại không đúng.");String password=str(b,"password");passwordForAccount(password);a.passwordHash=encoder.encode(password);a.tokenVersion++;if("RESET".equals(a.otpPurpose))a.otpHash=null;}
 Address address(Map<String,Object>b){Account a=me();boolean fresh=str(b,"id").isEmpty();Address d=fresh?new Address():get(Address.class,number(b,"id"));forbidden(fresh||Objects.equals(d.userId,a.id));String label=str(b,"label"),recipient=str(b,"recipient"),phone=str(b,"phone"),detail=str(b,"detail"),defaultValue=str(b,"defaultAddress");require(!label.isEmpty()&&label.length()<=100,"Tên gợi nhớ không hợp lệ.");require(recipient.length()>=2&&recipient.length()<=100,"Tên người nhận không hợp lệ.");require(phone.matches("[+0-9 ()-]{8,20}"),"Số điện thoại không hợp lệ.");require(detail.length()>=8&&detail.length()<=500,"Địa chỉ cần từ 8 đến 500 ký tự.");require(defaultValue.isEmpty()||List.of("true","false").contains(defaultValue),"Địa chỉ mặc định không hợp lệ.");boolean makeDefault=Boolean.parseBoolean(defaultValue);if(makeDefault)where(Address.class,"userId",a.id).stream().filter(x->!Objects.equals(x.id,d.id)).forEach(x->x.defaultAddress=false);d.userId=a.id;d.label=label;d.recipient=recipient;d.phone=phone;d.detail=detail;d.defaultAddress=makeDefault;if(d.id==null)save(d);return d;}
 void deleteAddress(long id){Address d=get(Address.class,id);forbidden(Objects.equals(d.userId,me().id));em.remove(d);}
 record Quote(BigDecimal price,int calories,String description,String ids){}
 Quote quote(Product p,String ids){BigDecimal price=p.price;int kcal=p.calories;List<String>names=new ArrayList<>();Set<Long>unique=new LinkedHashSet<>();Map<String,Integer>counts=new HashMap<>();if(ids!=null&&!ids.isBlank())for(String s:ids.split(",")){long id;try{id=Long.parseLong(s.trim());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Thành phần không hợp lệ.");}require(unique.add(id),"Thành phần trùng lặp.");Ingredient i=get(Ingredient.class,id);require(i.available,"Thành phần tạm hết: "+i.name);counts.merge(i.groupName,1,Integer::sum);price=price.add(i.price);kcal+=i.calories;names.add(i.name);}
  if(p.customizable){for(String group:List.of("PROTEIN","RICE","BEANS","SAUCE"))require(counts.getOrDefault(group,0)==1,"Vui lòng chọn đúng một thành phần nhóm "+group+".");}else require(unique.isEmpty(),"Món này không có thành phần tùy chọn.");
  return new Quote(money(price),kcal,String.join(" · ",names),unique.stream().map(Object::toString).collect(Collectors.joining(",")));
 }
 CartLine cart(Map<String,Object>b){Account a=me();CartLine c=str(b,"id").isEmpty()?new CartLine():get(CartLine.class,number(b,"id"));forbidden(c.userId==null||c.userId.equals(a.id));Product p=get(Product.class,number(b,"productId"));require(p.available&&get(Store.class,p.storeId).active,"Món tạm ngừng bán.");int q=(int)number(b,"quantity");require(q>=1&&q<=50&&q<=p.stock,"Số lượng phải từ 1 đến 50 và không vượt tồn kho.");Quote qt=quote(p,str(b,"ingredientIds"));c.userId=a.id;c.productId=p.id;c.storeId=p.storeId;c.quantity=q;c.ingredientIds=qt.ids;c.note=str(b,"note");require(c.note.length()<=300,"Ghi chú tối đa 300 ký tự.");if(c.id==null)save(c);return c;}
 List<Map<String,Object>> cartView(){
  List<CartLine> lines=where(CartLine.class,"userId",me().id);
  Map<Long,Integer> quantities=new HashMap<>();lines.forEach(c->quantities.merge(c.productId,c.quantity,Integer::sum));
  return lines.stream().map(c->{
   Product p=em.find(Product.class,c.productId);Store store=em.find(Store.class,c.storeId);
   List<String> issues=new ArrayList<>();Quote q=null;
   if(p==null)issues.add("Món không còn tồn tại. Vui lòng xóa khỏi giỏ.");
   if(store==null||!store.active)issues.add("Chi nhánh tạm ngừng phục vụ.");
   if(p!=null){
    if(!p.available)issues.add("Món tạm ngừng bán.");
    if(!Objects.equals(p.storeId,c.storeId))issues.add("Món đã thay đổi chi nhánh. Vui lòng chọn lại từ thực đơn.");
    if(c.quantity<1||c.quantity>50||quantities.get(p.id)>p.stock)issues.add("Tổng số lượng món trong giỏ vượt tồn kho hoặc giới hạn. Vui lòng sửa số lượng.");
    try{q=quote(p,c.ingredientIds);}catch(ResponseStatusException e){
     if(e.getStatusCode().value()!=400&&e.getStatusCode().value()!=404)throw e;
     issues.add(e.getStatusCode().value()==404?"Thành phần không còn tồn tại. Vui lòng chọn lại món.":e.getReason());
    }
   }
   Map<String,Object> row=new LinkedHashMap<>();row.put("line",c);row.put("product",p);
   row.put("available",issues.isEmpty());row.put("issues",issues);
   row.put("editable",p!=null&&p.available&&store!=null&&store.active&&Objects.equals(p.storeId,c.storeId));
   row.put("unitPrice",q==null?null:q.price);row.put("calories",q==null?null:q.calories);
   row.put("customization",q==null?"Cần chọn lại thành phần":q.description);
   row.put("total",q==null?null:q.price.multiply(BigDecimal.valueOf(c.quantity)));return row;
  }).toList();
 }
 void deleteCart(long id){CartLine c=get(CartLine.class,id);forbidden(c.userId.equals(me().id));em.remove(c);}
 Voucher findVoucher(String code){return em.createQuery("from Voucher where code=:c",Voucher.class).setParameter("c",code.toUpperCase(Locale.ROOT)).getResultStream().findFirst().orElse(null);}
 BigDecimal discount(Voucher v,BigDecimal subtotal){return money(("PERCENT".equals(v.type)?subtotal.multiply(v.value).divide(BigDecimal.valueOf(100)):v.value).min(v.maxDiscount).min(subtotal).max(BigDecimal.ZERO));}
 Map<String,Object> preview(Map<String,Object>b){return calculate(b,false);}
 Map<String,Object> calculate(Map<String,Object>b,boolean reserve){Account a=me();List<CartLine> lines=where(CartLine.class,"userId",a.id);require(!lines.isEmpty(),"Giỏ hàng trống.");Map<Long,List<CartLine>>groups=lines.stream().collect(Collectors.groupingBy(c->c.storeId,LinkedHashMap::new,Collectors.toList()));String type=str(b,"type");require(List.of("PICKUP","DELIVERY").contains(type),"Chọn nhận tại cửa hàng hoặc giao tận nơi.");List<Map<String,Object>>parts=new ArrayList<>();BigDecimal full=BigDecimal.ZERO,eligible=BigDecimal.ZERO,fees=BigDecimal.ZERO;Map<Long,BigDecimal>subtotals=new LinkedHashMap<>();Voucher v=null;String code=str(b,"voucher");
  if(!code.isEmpty()){v=findVoucher(code);require(v!=null,"Mã khuyến mãi không tồn tại.");if(reserve)em.lock(v,LockModeType.PESSIMISTIC_WRITE);require(v.active&&v.startsAt.isBefore(LocalDateTime.now())&&v.endsAt.isAfter(LocalDateTime.now())&&v.used<v.usageLimit,"Mã đã hết hạn hoặc hết lượt sử dụng.");require(v.userId==null||v.userId.equals(a.id),"Mã không thuộc tài khoản này.");}
  for(var entry:groups.entrySet()){Store store=get(Store.class,entry.getKey());require(store.active&&("PICKUP".equals(type)?store.pickup:store.delivery),"Chi nhánh không phục vụ phương thức nhận món này.");BigDecimal sub=BigDecimal.ZERO;Map<Long,Integer>quantities=new HashMap<>();for(CartLine c:entry.getValue()){Product p=get(Product.class,c.productId);if(reserve)em.lock(p,LockModeType.PESSIMISTIC_WRITE);require(Objects.equals(p.storeId,c.storeId),"Món đã thay đổi chi nhánh. Vui lòng chọn lại từ thực đơn.");require(c.quantity>=1&&c.quantity<=50,"Số lượng phải từ 1 đến 50.");quantities.merge(p.id,c.quantity,Integer::sum);require(p.available&&p.stock>=quantities.get(p.id),"Món đã hết hoặc không đủ tồn kho: "+p.name);sub=sub.add(quote(p,c.ingredientIds).price.multiply(BigDecimal.valueOf(c.quantity)));}subtotals.put(store.id,sub);full=full.add(sub);if(v==null||v.storeId==null||v.storeId.equals(store.id))eligible=eligible.add(sub);}
  BigDecimal off=BigDecimal.ZERO;if(v!=null){require(eligible.compareTo(v.minimum)>=0&&eligible.signum()>0,"Đơn chưa đạt điều kiện áp dụng mã.");off=discount(v,eligible);}
  BigDecimal allocated=BigDecimal.ZERO;List<Long>eligibleStores=subtotals.keySet().stream().filter(id->{Voucher vv=code.isEmpty()?null:findVoucher(code);return vv==null||vv.storeId==null||vv.storeId.equals(id);}).toList();
  for(var entry:subtotals.entrySet()){Store s=get(Store.class,entry.getKey());BigDecimal sub=entry.getValue(),partOff=BigDecimal.ZERO;if(eligibleStores.contains(s.id)&&eligible.signum()>0){if(s.id.equals(eligibleStores.getLast()))partOff=off.subtract(allocated);else partOff=money(off.multiply(sub).divide(eligible,8,RoundingMode.HALF_UP));allocated=allocated.add(partOff);}BigDecimal fee="DELIVERY".equals(type)&&sub.compareTo(new BigDecimal("150000"))<0?s.deliveryFee:BigDecimal.ZERO;fees=fees.add(fee);parts.add(Map.of("store",s,"subtotal",sub,"discount",partOff,"deliveryFee",fee,"total",sub.subtract(partOff).add(fee)));}
  return Map.of("parts",parts,"subtotal",full,"discount",off,"deliveryFee",fees,"total",full.subtract(off).add(fees));
 }
 List<MealOrder> checkout(Map<String,Object>b){Account a=me();em.lock(a,LockModeType.PESSIMISTIC_WRITE);String key=str(b,"checkoutKey");require(key.matches("[a-zA-Z0-9-]{12,80}"),"Mã yêu cầu đặt hàng không hợp lệ.");List<MealOrder>old=em.createQuery("from MealOrder where userId=:u and checkoutKey=:k",MealOrder.class).setParameter("u",a.id).setParameter("k",key).getResultList();if(!old.isEmpty())return old;
  String method=str(b,"paymentMethod"),type=str(b,"type"),name=str(b,"contactName"),phone=str(b,"phone"),scheduled=str(b,"scheduledAt");require(List.of("COD","VNPAY","MOMO").contains(method),"Phương thức thanh toán không hợp lệ.");require(name.length()>=2&&phone.matches("[+0-9 ()-]{8,20}"),"Vui lòng nhập tên và số điện thoại hợp lệ.");String address="";if("DELIVERY".equals(type)){if(!str(b,"addressId").isEmpty()){Address d=get(Address.class,number(b,"addressId"));forbidden(d.userId.equals(a.id));address=d.detail;}else address=str(b,"address");require(address.length()>=8&&address.length()<=500,"Nhập địa chỉ giao hàng đầy đủ.");}
  if(!scheduled.isEmpty()&&!"ASAP".equals(scheduled)){try{LocalDateTime t=LocalDateTime.parse(scheduled);require(t.isAfter(LocalDateTime.now().plusMinutes(30))&&t.isBefore(LocalDateTime.now().plusDays(7)),"Giờ hẹn cần sau 30 phút và trong 7 ngày tới.");}catch(java.time.format.DateTimeParseException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Giờ hẹn không hợp lệ.");}}
  Map<String,Object>calc=calculate(b,true);List<CartLine>lines=where(CartLine.class,"userId",a.id);List<MealOrder>result=new ArrayList<>();String group="UTEB-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);
  for(Object obj:(List<?>)calc.get("parts")){Map<?,?>part=(Map<?,?>)obj;Store store=(Store)part.get("store");MealOrder o=new MealOrder();o.userId=a.id;o.storeId=store.id;o.code=group+"-"+store.id;o.groupCode=group;o.checkoutKey=key;o.type=type;o.paymentMethod=method;o.contactName=name;o.phone=phone;o.address=address;o.note=str(b,"note");o.scheduledAt=scheduled.isEmpty()?"ASAP":scheduled;o.voucherCode=str(b,"voucher").toUpperCase(Locale.ROOT);o.subtotal=(BigDecimal)part.get("subtotal");o.discount=(BigDecimal)part.get("discount");o.deliveryFee=(BigDecimal)part.get("deliveryFee");o.total=(BigDecimal)part.get("total");o.commissionRate=store.commission;o.paymentStatus="COD".equals(method)?"UNPAID":"PENDING";o.paymentExpires=LocalDateTime.now().plusMinutes(15);save(o);
   for(CartLine c:lines)if(c.storeId.equals(store.id)){Product p=get(Product.class,c.productId);Quote qt=quote(p,c.ingredientIds);p.stock-=c.quantity;OrderLine l=new OrderLine();l.orderId=o.id;l.productId=p.id;l.name=p.name;l.image=p.image;l.quantity=c.quantity;l.unitPrice=qt.price;l.calories=qt.calories;l.customization=qt.description+(c.note.isEmpty()?"":" | "+c.note);save(l);}
   event(o,"NEW","Đã đặt đơn",a.id);notifyUser(a.id,o.id,"Đã nhận đơn "+o.code);for(Account operator:all(Account.class))if(operator.active&&Objects.equals(operator.storeId,store.id)&&has(operator,"STAFF","MANAGER","VENDOR"))notifyUser(operator.id,o.id,"Đơn mới "+o.code);result.add(o);
  }
  if(!str(b,"voucher").isEmpty())findVoucher(str(b,"voucher")).used++;lines.forEach(em::remove);return result;
 }
 void event(MealOrder o,String status,String text,Long actor){OrderEvent e=new OrderEvent();e.orderId=o.id;e.status=status;e.description=text;e.actorId=actor;save(e);o.updatedAt=LocalDateTime.now();}
 void notifyUser(Long userId,Long orderId,String text){Notice n=new Notice();n.userId=userId;n.orderId=orderId;n.text=text;save(n);Account a=get(Account.class,userId);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){socket.convertAndSendToUser(a.email,"/queue/events",Map.of("text",text,"orderId",orderId==null?-1L:orderId));}});}
 List<MealOrder> orders(){Account a=me();return all(MealOrder.class).stream().filter(o->has(a,"ADMIN")||o.userId.equals(a.id)||(has(a,"STAFF","MANAGER","VENDOR")&&Objects.equals(a.storeId,o.storeId))||(has(a,"SHIPPER")&&Objects.equals(a.id,o.shipperId))).toList();}
 MealOrder accessibleOrder(long id){MealOrder o=get(MealOrder.class,id);Account a=me();forbidden(has(a,"ADMIN")||o.userId.equals(a.id)||(has(a,"STAFF","MANAGER","VENDOR")&&Objects.equals(a.storeId,o.storeId))||(has(a,"SHIPPER")&&Objects.equals(a.id,o.shipperId)));return o;}
 Map<String,Object> detail(long id){MealOrder o=accessibleOrder(id);return Map.of("order",o,"items",where(OrderLine.class,"orderId",o.id),"events",where(OrderEvent.class,"orderId",o.id),"refunds",where(RefundRequest.class,"orderId",o.id),"store",get(Store.class,o.storeId));}
 void status(long id,Map<String,Object>b){MealOrder o=accessibleOrder(id);em.lock(o,LockModeType.PESSIMISTIC_WRITE);Account a=me();String next=str(b,"status");
  if("CANCELLED".equals(next)){require(List.of("NEW","CONFIRMED").contains(o.status),"Chỉ hủy trước khi chế biến.");if(!o.userId.equals(a.id))manageStore(a,o.storeId);require(!"PAID".equals(o.paymentStatus),"Đơn đã thanh toán cần được xử lý hoàn tiền có bằng chứng.");for(OrderLine l:where(OrderLine.class,"orderId",o.id)){Product p=get(Product.class,l.productId);em.lock(p,LockModeType.PESSIMISTIC_WRITE);p.stock+=l.quantity;}o.status=next;o.paymentStatus="CANCELLED";
  }else{
   List<String>flow="DELIVERY".equals(o.type)?List.of("NEW","CONFIRMED","PREPARING","READY","DELIVERING","COMPLETED"):List.of("NEW","CONFIRMED","PREPARING","READY","COMPLETED");int ix=flow.indexOf(o.status);require(ix>=0&&ix+1<flow.size()&&flow.get(ix+1).equals(next),"Không thể chuyển sang trạng thái này.");if(has(a,"SHIPPER")&&!has(a,"ADMIN","MANAGER","STAFF","VENDOR")){forbidden(Objects.equals(o.shipperId,a.id)&&List.of("DELIVERING","COMPLETED").contains(next));}else manageStore(a,o.storeId);
   require("COD".equals(o.paymentMethod)||"PAID".equals(o.paymentStatus),"Đơn chưa thanh toán trực tuyến.");if("DELIVERING".equals(next))require(o.shipperId!=null,"Vui lòng phân công người giao hàng trước.");o.status=next;if("COMPLETED".equals(next)){if("COD".equals(o.paymentMethod)){require(Boolean.parseBoolean(str(b,"codCollected")),"Xác nhận đã thu đủ COD.");o.paymentStatus="PAID";o.transactionRef="COD-"+o.code;}awardPoints(o);}
  }event(o,next,str(b,"note").isEmpty()?"Cập nhật trạng thái":str(b,"note"),a.id);notifyUser(o.userId,o.id,"Đơn "+o.code+": "+next);audit("ORDER_STATUS",o.code+" → "+next);
 }
 void assignmentAllowed(MealOrder o){require("DELIVERY".equals(o.type),"Chỉ phân công shipper cho đơn giao tận nơi.");require(List.of("NEW","CONFIRMED","PREPARING","READY").contains(o.status),"Chỉ phân công trước khi đơn bắt đầu giao; không đổi đơn đã hoàn tất hoặc hủy.");}
 List<Map<String,Object>> shippers(Long orderId){
  Account actor=me();forbidden(has(actor,"ADMIN","MANAGER","VENDOR"));Long storeId=actor.storeId;
  if(orderId!=null){MealOrder o=accessibleOrder(orderId);managerStore(actor,o.storeId);assignmentAllowed(o);storeId=o.storeId;}
  final Long branch=storeId;
  return all(Account.class).stream().filter(u->u.active&&u.verified&&has(u,"SHIPPER")&&(orderId==null&&has(actor,"ADMIN")||Objects.equals(u.storeId,branch)))
   .map(u->Map.<String,Object>of("id",u.id,"name",u.name)).toList();
 }
 void assign(long id,long shipperId){MealOrder o=accessibleOrder(id);managerStore(me(),o.storeId);em.lock(o,LockModeType.PESSIMISTIC_WRITE);assignmentAllowed(o);Account shipper=get(Account.class,shipperId);require(shipper.active&&shipper.verified&&has(shipper,"SHIPPER"),"Người giao hàng không hợp lệ hoặc chưa xác thực.");require(Objects.equals(shipper.storeId,o.storeId),"Shipper phải thuộc cùng chi nhánh với đơn hàng.");if(Objects.equals(o.shipperId,shipperId))return;o.shipperId=shipperId;notifyUser(shipperId,o.id,"Bạn được giao đơn "+o.code);event(o,o.status,"Phân công "+shipper.name,me().id);}
 void awardPoints(MealOrder o){if(o.pointsAwarded)return;Account a=get(Account.class,o.userId);em.lock(a,LockModeType.PESSIMISTIC_WRITE);int points=o.total.divide(new BigDecimal("1000"),0,RoundingMode.DOWN).intValue();a.points+=points;o.pointsAwarded=true;RewardLog l=new RewardLog();l.userId=a.id;l.points=points;l.description="Đơn "+o.code;save(l);}
 void paymentResult(long id,String ref,boolean success){MealOrder o=get(MealOrder.class,id);em.lock(o,LockModeType.PESSIMISTIC_WRITE);if("PAID".equals(o.paymentStatus))return;require(!"CANCELLED".equals(o.status)&&o.paymentExpires.isAfter(LocalDateTime.now()),"Đơn đã hủy hoặc hết hạn; cần đối soát giao dịch đến muộn.");o.transactionRef=ref;o.paymentStatus=success?"PAID":"FAILED";event(o,o.status,success?"Đã xác minh thanh toán":"Thanh toán thất bại",null);notifyUser(o.userId,o.id,success?"Đã thanh toán "+o.code:"Thanh toán thất bại "+o.code);}
 void simulate(long id,boolean success){require(demo,"Giả lập chỉ khả dụng ở profile demo.");MealOrder o=accessibleOrder(id);forbidden(o.userId.equals(me().id));require("MOMO".equals(o.paymentMethod),"VNPay và COD không sử dụng thanh toán giả lập.");paymentResult(id,"LOCAL-SIM-"+UUID.randomUUID(),success);}
 Review review(Map<String,Object>b){Account a=me();OrderLine l=get(OrderLine.class,number(b,"orderLineId"));MealOrder o=get(MealOrder.class,l.orderId);forbidden(o.userId.equals(a.id));require("COMPLETED".equals(o.status),"Chỉ đánh giá sau khi đã nhận món.");require(where(Review.class,"orderLineId",l.id).isEmpty(),"Bạn đã đánh giá món này.");int stars=(int)number(b,"stars");String text=str(b,"text");require(stars>=1&&stars<=5&&text.length()>=50&&text.length()<=3000,"Đánh giá cần 1–5 sao và 50–3000 ký tự.");Review r=new Review();r.userId=a.id;r.author=a.name;r.productId=l.productId;r.orderLineId=l.id;r.stars=stars;r.text=text;String media=str(b,"media");if(!media.isEmpty()){List<String>urls=Arrays.asList(media.split(","));require(urls.size()<=3,"Tối đa 3 ảnh/video.");for(String u:urls)require(where(MediaRecord.class,"userId",a.id).stream().anyMatch(m->m.url.equals(u)),"Media không thuộc tài khoản.");r.media=media;}return save(r);}
 void mark(long productId,String kind){require(List.of("FAVORITE","RECENT").contains(kind),"Loại dấu không hợp lệ.");get(Product.class,productId);Account a=me();List<UserMark>old=em.createQuery("from UserMark where userId=:u and productId=:p and kind=:k",UserMark.class).setParameter("u",a.id).setParameter("p",productId).setParameter("k",kind).getResultList();if(!old.isEmpty()){if("FAVORITE".equals(kind))em.remove(old.getFirst());else old.getFirst().createdAt=LocalDateTime.now();}else{UserMark m=new UserMark();m.userId=a.id;m.productId=productId;m.kind=kind;save(m);}}
 Map<String,Object> accountData(){Account a=me();return Map.of("user",a,"addresses",where(Address.class,"userId",a.id),"marks",where(UserMark.class,"userId",a.id),"notifications",where(Notice.class,"userId",a.id),"rewardHistory",where(RewardLog.class,"userId",a.id),"rewardVouchers",where(Voucher.class,"userId",a.id),"applications",where(ShopApplication.class,"userId",a.id));}
 void readNotice(long id){Notice n=get(Notice.class,id);forbidden(n.userId.equals(me().id));n.seen=true;}
 Voucher redeem(String reward){Account a=me();em.lock(a,LockModeType.PESSIMISTIC_WRITE);int cost;BigDecimal amount;switch(reward){case"DRINK":cost=500;amount=new BigDecimal("25000");break;case"CHIPS":cost=800;amount=new BigDecimal("35000");break;case"BURRITO":cost=1200;amount=new BigDecimal("89000");break;default:throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Phần thưởng không hợp lệ.");}require(a.points>=cost,"Bạn chưa đủ điểm.");a.points-=cost;Voucher v=new Voucher();v.code="RW"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase(Locale.ROOT);v.name="Đổi thưởng "+reward;v.userId=a.id;v.type="FIXED";v.value=amount;v.maxDiscount=amount;v.usageLimit=1;save(v);RewardLog l=new RewardLog();l.userId=a.id;l.points=-cost;l.description="Đổi "+reward+": "+v.code;save(l);return v;}
 GroupMeal createGroup(Map<String,Object>b){GroupMeal g=new GroupMeal();g.organizerId=me().id;g.storeId=number(b,"storeId");get(Store.class,g.storeId);g.title=str(b,"title");require(g.title.length()>=2&&g.title.length()<=100,"Tên nhóm không hợp lệ.");g.code=UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);return save(g);}
 GroupMeal group(String code){GroupMeal g=em.createQuery("from GroupMeal where code=:c",GroupMeal.class).setParameter("c",code.toUpperCase(Locale.ROOT)).getResultStream().findFirst().orElse(null);if(g==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Nhóm không tồn tại.");return g;}
 Map<String,Object> groupView(String code){GroupMeal g=group(code);return Map.of("group",g,"lines",where(GroupLine.class,"groupId",g.id));}
 GroupLine groupAdd(String code,Map<String,Object>b){GroupMeal g=group(code);require("OPEN".equals(g.status),"Nhóm đã khóa.");Product p=get(Product.class,number(b,"productId"));require(p.available&&p.storeId.equals(g.storeId),"Món cần thuộc chi nhánh của nhóm.");GroupLine l=new GroupLine();l.groupId=g.id;l.userId=me().id;l.memberName=me().name;l.productId=p.id;l.ingredientIds=quote(p,str(b,"ingredientIds")).ids;l.quantity=(int)number(b,"quantity");require(l.quantity>=1&&l.quantity<=50,"Số lượng không hợp lệ.");return save(l);}
 void groupDelete(long id){GroupLine l=get(GroupLine.class,id);GroupMeal g=get(GroupMeal.class,l.groupId);forbidden(l.userId.equals(me().id)||g.organizerId.equals(me().id));require("OPEN".equals(g.status),"Nhóm đã khóa.");em.remove(l);}
 void groupToCart(String code){GroupMeal g=group(code);em.lock(g,LockModeType.PESSIMISTIC_WRITE);forbidden(g.organizerId.equals(me().id));require("OPEN".equals(g.status),"Nhóm đã được chuyển vào giỏ.");List<GroupLine> ls=where(GroupLine.class,"groupId",g.id);require(!ls.isEmpty(),"Nhóm chưa có món.");for(GroupLine l:ls)cart(Map.of("productId",l.productId,"quantity",l.quantity,"ingredientIds",l.ingredientIds,"note","Nhóm "+g.title+" – "+l.memberName));g.status="LOCKED";}
 CateringRequest catering(Map<String,Object>b){CateringRequest c=new CateringRequest();c.userId=me().id;c.storeId=number(b,"storeId");get(Store.class,c.storeId);c.packageName=str(b,"packageName");require(List.of("Burrito Box","Build Your Own Party","Chips & Salsa").contains(c.packageName),"Gói tiệc không hợp lệ.");c.people=(int)number(b,"people");require(c.people>=10&&c.people<=500,"Số khách từ 10 đến 500.");c.eventAt=str(b,"eventAt");try{require(LocalDateTime.parse(c.eventAt).isAfter(LocalDateTime.now().plusDays(1)),"Đặt tiệc trước ít nhất 24 giờ.");}catch(java.time.format.DateTimeParseException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Ngày giờ không hợp lệ.");}c.contactName=str(b,"contactName");c.phone=str(b,"phone");c.address=str(b,"address");c.note=str(b,"note");require(c.contactName.length()>=2&&c.phone.matches("[+0-9 ()-]{8,20}"),"Thông tin liên hệ không hợp lệ.");c.quotedTotal=BigDecimal.valueOf(c.people).multiply(new BigDecimal("Chips & Salsa".equals(c.packageName)?"45000":"99000"));return save(c);}
 RefundRequest refund(long id,Map<String,Object>b){MealOrder o=accessibleOrder(id);forbidden(o.userId.equals(me().id));require("COMPLETED".equals(o.status)&&"PAID".equals(o.paymentStatus),"Chỉ yêu cầu hoàn tiền cho đơn đã hoàn tất và thanh toán.");require(where(RefundRequest.class,"orderId",o.id).isEmpty(),"Đơn đã có yêu cầu hoàn.");String reason=str(b,"reason");require(reason.length()>=20&&reason.length()<=2000,"Lý do cần 20–2000 ký tự.");RefundRequest r=new RefundRequest();r.userId=o.userId;r.orderId=o.id;r.storeId=o.storeId;r.reason=reason;r.amount=o.total;return save(r);}
 void refundDecision(long id,Map<String,Object>b){RefundRequest r=get(RefundRequest.class,id);managerStore(me(),r.storeId);MealOrder o=get(MealOrder.class,r.orderId);em.lock(r,LockModeType.PESSIMISTIC_WRITE);String status=str(b,"status");require(List.of("APPROVED","REJECTED","REFUNDED").contains(status),"Trạng thái hoàn không hợp lệ.");if("REFUNDED".equals(status)){require("APPROVED".equals(r.status),"Cần duyệt trước khi hoàn.");String evidence=str(b,"evidence");require(evidence.length()>=8,"Cần mã giao dịch hoặc bằng chứng hoàn tiền.");r.evidence=evidence;o.paymentStatus="REFUNDED";if(o.pointsAwarded){Account a=get(Account.class,o.userId);int points=o.total.divide(new BigDecimal("1000"),0,RoundingMode.DOWN).intValue();a.points=Math.max(0,a.points-points);RewardLog l=new RewardLog();l.userId=a.id;l.points=-points;l.description="Hoàn đơn "+o.code;save(l);o.pointsAwarded=false;}}else require("REQUESTED".equals(r.status),"Yêu cầu đã xử lý.");r.status=status;r.reply=str(b,"reply");notifyUser(r.userId,o.id,"Yêu cầu hoàn "+o.code+": "+status);audit("REFUND",o.code+" "+status);}
 ShopApplication shopApplication(Map<String,Object>b){ShopApplication s=new ShopApplication();s.userId=me().id;s.name=str(b,"name");s.address=str(b,"address");s.phone=str(b,"phone");require(s.name.length()>=3&&s.address.length()>=8,"Nhập tên và địa chỉ cửa hàng.");return save(s);}
 void approveShop(long id,Map<String,Object>b){forbidden(has(me(),"ADMIN"));ShopApplication s=get(ShopApplication.class,id);require("PENDING".equals(s.status),"Đã xử lý yêu cầu.");s.reply=str(b,"reply");if(Boolean.parseBoolean(str(b,"approve"))){Account a=get(Account.class,s.userId);require(a.storeId==null,"Tài khoản đã quản lý một cửa hàng.");Store store=new Store();store.name=s.name;store.address=s.address;store.phone=s.phone;store.ownerId=a.id;save(store);a.storeId=store.id;a.roles="CUSTOMER,VENDOR";s.status="APPROVED";}else s.status="REJECTED";audit("SHOP_APPROVAL",s.name+" "+s.status);}
 Map<String,Object> dashboard(){Account a=me();forbidden(has(a,"ADMIN","MANAGER","VENDOR","STAFF","SHIPPER"));List<MealOrder>os=orders().stream().filter(o->has(a,"ADMIN")||Objects.equals(o.storeId,a.storeId)||(has(a,"SHIPPER")&&Objects.equals(o.shipperId,a.id))).toList();BigDecimal revenue=os.stream().filter(o->"COMPLETED".equals(o.status)&&"PAID".equals(o.paymentStatus)).map(o->o.total).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal commission=os.stream().filter(o->"COMPLETED".equals(o.status)&&"PAID".equals(o.paymentStatus)).map(o->money(o.subtotal.subtract(o.discount).multiply(o.commissionRate))).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,BigDecimal>daily=new TreeMap<>();Map<String,Integer>top=new HashMap<>();for(MealOrder o:os)if("COMPLETED".equals(o.status)&&"PAID".equals(o.paymentStatus)){daily.merge(o.createdAt.toLocalDate().toString(),o.total,BigDecimal::add);for(OrderLine l:where(OrderLine.class,"orderId",o.id))top.merge(l.name,l.quantity,Integer::sum);}return Map.of("orders",os,"revenue",revenue,"commission",commission,"net",revenue.subtract(commission),"customers",os.stream().map(o->o.userId).distinct().count(),"daily",daily,"topProducts",top,"stores",all(Store.class).size());}
 void audit(String action,String detail){AuditRecord r=new AuditRecord();r.actorId=me().id;r.action=action;r.detail=detail;save(r);}
 public List<?> adminList(String resource){Account a=me();switch(resource){case"products":forbidden(has(a,"ADMIN","MANAGER","VENDOR"));return all(Product.class).stream().filter(p->has(a,"ADMIN")||Objects.equals(p.storeId,a.storeId)).toList();case"stores":forbidden(has(a,"ADMIN","MANAGER","VENDOR"));return all(Store.class).stream().filter(s->has(a,"ADMIN")||Objects.equals(s.id,a.storeId)).toList();case"ingredients":case"categories":forbidden(has(a,"ADMIN","MANAGER","VENDOR"));return resource.equals("ingredients")?all(Ingredient.class):all(Category.class);case"vouchers":forbidden(has(a,"ADMIN","MANAGER","VENDOR"));return all(Voucher.class).stream().filter(v->has(a,"ADMIN")||Objects.equals(v.storeId,a.storeId)).toList();case"users":forbidden(has(a,"ADMIN","MANAGER"));return all(Account.class).stream().filter(u->has(a,"ADMIN")||(Objects.equals(u.storeId,a.storeId)&&managerUserTarget(u))).toList();case"shippers":return shippers(null);case"refunds":forbidden(has(a,"ADMIN","MANAGER","VENDOR"));return all(RefundRequest.class).stream().filter(r->has(a,"ADMIN")||Objects.equals(r.storeId,a.storeId)).toList();case"catering":forbidden(has(a,"ADMIN","MANAGER","VENDOR"));return all(CateringRequest.class).stream().filter(c->has(a,"ADMIN")||Objects.equals(c.storeId,a.storeId)).toList();case"applications":forbidden(has(a,"ADMIN"));return all(ShopApplication.class);case"audit":forbidden(has(a,"ADMIN"));return all(AuditRecord.class);case"settings":forbidden(has(a,"ADMIN"));return all(Setting.class);case"media":return has(a,"ADMIN")?all(MediaRecord.class):where(MediaRecord.class,"userId",a.id);default:throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Module không tồn tại.");}}
 public Object adminSave(String resource,Map<String,Object>b){Account a=me();boolean fresh=str(b,"id").isEmpty();long id=fresh?0:number(b,"id");Object result;
  switch(resource){
   case"products":{Product p=fresh?new Product():get(Product.class,id);Long store=number(b,"storeId");if(!fresh)managerStore(a,p.storeId);managerStore(a,store);p.storeId=store;p.name=str(b,"name");p.category=str(b,"category");require(!where(Category.class,"name",p.category).isEmpty(),"Danh mục không tồn tại.");p.description=str(b,"description");p.price=new BigDecimal(str(b,"price"));p.stock=(int)number(b,"stock");p.calories=(int)number(b,"calories");p.available=Boolean.parseBoolean(str(b,"available"));p.customizable=Boolean.parseBoolean(str(b,"customizable"));require(p.name.length()>=2&&p.price.signum()>0&&p.price.compareTo(new BigDecimal("10000000"))<=0&&p.stock>=0&&p.calories>=0,"Tên, giá, tồn kho hoặc calories không hợp lệ.");String image=str(b,"image");if(!image.isEmpty()){require(image.startsWith("/assets/")||image.startsWith("https://res.cloudinary.com/"),"Ảnh cần là media đã tải lên hoặc ảnh nội bộ.");p.image=image;}result=p;break;}
   case"stores":{Store s=fresh?new Store():get(Store.class,id);if(fresh)forbidden(has(a,"ADMIN"));else managerStore(a,s.id);s.name=str(b,"name");s.address=str(b,"address");s.phone=str(b,"phone");s.hours=str(b,"hours");s.pickup=Boolean.parseBoolean(str(b,"pickup"));s.delivery=Boolean.parseBoolean(str(b,"delivery"));s.active=Boolean.parseBoolean(str(b,"active"));s.deliveryFee=new BigDecimal(str(b,"deliveryFee"));if(has(a,"ADMIN"))s.commission=new BigDecimal(str(b,"commission"));require(s.name.length()>2&&s.address.length()>5&&s.deliveryFee.signum()>=0&&s.commission.signum()>=0&&s.commission.compareTo(BigDecimal.ONE)<=0,"Thông tin cửa hàng không hợp lệ.");result=s;break;}
   case"ingredients":{forbidden(has(a,"ADMIN"));Ingredient i=fresh?new Ingredient():get(Ingredient.class,id);i.name=str(b,"name");i.groupName=str(b,"groupName");require(List.of("PROTEIN","RICE","BEANS","SAUCE","TOPPING","EXTRA").contains(i.groupName),"Nhóm thành phần không hợp lệ.");i.price=new BigDecimal(str(b,"price"));i.calories=(int)number(b,"calories");i.available=Boolean.parseBoolean(str(b,"available"));i.allergens=str(b,"allergens");require(i.name.length()>=2&&i.price.signum()>=0&&i.calories>=0,"Thành phần không hợp lệ.");result=i;break;}
   case"categories":{forbidden(has(a,"ADMIN"));Category c=fresh?new Category():get(Category.class,id);c.name=str(b,"name");c.slug=str(b,"slug");require(c.name.length()>=2&&c.slug.matches("[a-z0-9-]+"),"Danh mục không hợp lệ.");result=c;break;}
   case"vouchers":{Voucher v=fresh?new Voucher():get(Voucher.class,id);if(!fresh){if(v.storeId==null)forbidden(has(a,"ADMIN"));else managerStore(a,v.storeId);}Long store=str(b,"storeId").isEmpty()?null:number(b,"storeId");if(store==null)forbidden(has(a,"ADMIN"));else managerStore(a,store);v.storeId=store;v.code=str(b,"code").toUpperCase(Locale.ROOT);require(v.code.matches("[A-Z0-9]{3,30}"),"Mã cần 3–30 chữ/số.");Voucher existing=findVoucher(v.code);require(existing==null||Objects.equals(existing.id,v.id),"Mã đã tồn tại.");v.name=str(b,"name");v.type=str(b,"type");require(List.of("PERCENT","FIXED").contains(v.type),"Loại giảm giá không hợp lệ.");v.value=new BigDecimal(str(b,"value"));v.minimum=new BigDecimal(str(b,"minimum"));v.maxDiscount=new BigDecimal(str(b,"maxDiscount"));v.usageLimit=(int)number(b,"usageLimit");v.startsAt=LocalDateTime.parse(str(b,"startsAt"));v.endsAt=LocalDateTime.parse(str(b,"endsAt"));v.active=Boolean.parseBoolean(str(b,"active"));require(v.value.signum()>0&&v.minimum.signum()>=0&&v.maxDiscount.signum()>0&&v.usageLimit>=v.used&&v.endsAt.isAfter(v.startsAt)&&(!v.type.equals("PERCENT")||v.value.compareTo(new BigDecimal("100"))<=0),"Thông số khuyến mãi không hợp lệ.");result=v;break;}
   case"users":{forbidden(has(a,"ADMIN","MANAGER"));Account u=fresh?new Account():get(Account.class,id);if(!has(a,"ADMIN")){forbidden(!fresh&&Objects.equals(u.storeId,a.storeId)&&managerUserTarget(u));require(str(b,"roles").equals("STAFF")||str(b,"roles").equals("SHIPPER"),"Quản lý chỉ được thay đổi STAFF/SHIPPER của chi nhánh.");}String roles=str(b,"roles");require(Arrays.stream(roles.split(",",-1)).allMatch(r->List.of("CUSTOMER","STAFF","MANAGER","ADMIN","VENDOR","SHIPPER").contains(r)),"Role không hợp lệ.");if(u.id!=null&&u.id.equals(a.id))require(roles.contains("ADMIN")&&Boolean.parseBoolean(str(b,"active")),"Không thể tự khóa hoặc bỏ quyền của mình.");u.roles=roles;u.name=str(b,"name");u.email=str(b,"email").toLowerCase(Locale.ROOT);Account existing=byEmail(u.email);require(existing==null||Objects.equals(existing.id,u.id),"Email đã tồn tại.");u.phone=str(b,"phone");u.storeId=str(b,"storeId").isEmpty()?null:number(b,"storeId");if(!has(a,"ADMIN"))u.storeId=a.storeId;if(u.storeId!=null)get(Store.class,u.storeId);u.active=Boolean.parseBoolean(str(b,"active"));u.verified=true;String pwd=str(b,"password");if(fresh||!pwd.isEmpty()){passwordValid(pwd);u.passwordHash=encoder.encode(pwd);}u.tokenVersion++;result=u;break;}
   case"catering":{require(!fresh,"Không tạo catering ở màn hình quản trị.");CateringRequest c=get(CateringRequest.class,id);managerStore(a,c.storeId);require(List.of("NEW","CONFIRMED","COMPLETED","CANCELLED").contains(str(b,"status")),"Trạng thái không hợp lệ.");c.status=str(b,"status");notifyUser(c.userId,null,"Yêu cầu tiệc: "+c.status);result=c;break;}
   case"settings":{forbidden(has(a,"ADMIN"));Setting s=fresh?new Setting():get(Setting.class,id);s.name=str(b,"name");s.settingValue=str(b,"settingValue");require(s.name.length()>=2&&s.settingValue.length()<=250,"Cấu hình không hợp lệ.");result=s;break;}
   default:throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Module không hỗ trợ chỉnh sửa.");
  }if(fresh)save(result);audit("SAVE_"+resource,"ID="+((Base)result).id);return result;
 }
 public void adminDelete(String resource,long id){Account a=me();switch(resource){case"products":{Product p=get(Product.class,id);managerStore(a,p.storeId);p.available=false;break;}case"ingredients":{forbidden(has(a,"ADMIN"));get(Ingredient.class,id).available=false;break;}case"stores":{forbidden(has(a,"ADMIN"));get(Store.class,id).active=false;break;}case"vouchers":{Voucher v=get(Voucher.class,id);if(v.storeId==null)forbidden(has(a,"ADMIN"));else managerStore(a,v.storeId);v.active=false;break;}case"users":{forbidden(has(a,"ADMIN"));require(!me().id.equals(id),"Không tự khóa tài khoản.");get(Account.class,id).active=false;break;}case"categories":{forbidden(has(a,"ADMIN"));Category c=get(Category.class,id);require(where(Product.class,"category",c.name).isEmpty(),"Danh mục đang có sản phẩm.");em.remove(c);break;}default:throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Không hỗ trợ xóa ở module này.");}audit("DELETE_"+resource,"ID="+id);}
}
